const sys = "You are a research triage assistant. You read one scraped article and return ONLY a JSON object with exactly these fields: summary (2-3 sentence summary of the article substance), angle (one sentence - the content angle or hook that makes this usable for research/writing, or null), relevance (integer 1-5, 5 = directly useful now, 1 = noise), tags (array of 1-5 short lowercase topic tags). Return nothing except the JSON object.";
const user = 'TITLE: ' + title + '\n' + 'URL: ' + orig.canonical_url + '\n\nCONTENT:\n' + markdown.slice(0, 6000);
const triage_body = JSON.stringify({ model: 'qwen/qwen3.5-9b', temperature: 0.2, max_tokens: 4000,
  response_format: {"type":"json_schema","json_schema":{"name":"triage","strict":true,"schema":{"type":"object","properties":{"summary":{"type":"string"},"angle":{"type":["string","null"]},"relevance":{"type":"integer","minimum":1,"maximum":5},"tags":{"type":"array","items":{"type":"string"},"minItems":1,"maxItems":5}},"required":["summary","angle","relevance","tags"],"additionalProperties":false}}},
  messages: [ { role: 'system', content: sys }, { role: 'user', content: user } ] });
return { json: { canonical_url: orig.canonical_url, source: orig.source || '', title,
  markdown, scraper, run_id: orig.run_id, triage_body } };

function parseContent(j) {
  try {
    let c = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content;
    if (!c) return null;
    c = c.trim().replace(/^\`\`\`(json)?/i, '').replace(/\`\`\`$/, '').trim();
    const o = JSON.parse(c);
    if (o && typeof o.summary === 'string' && Number.isInteger(o.relevance) &&
        o.relevance >= 1 && o.relevance <= 5 && Array.isArray(o.tags) && o.tags.length >= 1) return o;
    return null;
  } catch (e) { return null; }
}
function tagsPg(tags) {
  const clean = (tags || []).slice(0, 5).map(t => String(t).toLowerCase().replace(/[{}",\\]/g, '').trim()).filter(Boolean);
  return '{' + clean.join(',') + '}';
}
